import json

def transform(grid):
    """Expand input to output based on observed pattern."""
    h_in, w_in = len(grid), len(grid[0])
    h_out = 2 * h_in - 1

    output = [[] for _ in range(h_out)]

    for r_in in range(h_in):
        if r_in == 0:
            start, end = 0, 2
        elif r_in == h_in - 1:
            start, end = h_out - 2, h_out
        else:
            start, end = r_in * 2, r_in * 2 + 1

        row_vals = []
        for c_in in range(w_in):
            if c_in == 0 or c_in == w_in - 1:
                row_vals.extend([grid[r_in][c_in]] * 2)
            else:
                row_vals.append(grid[r_in][c_in])

        for r_out in range(start, end):
            output[r_out] = row_vals[:w_in + 2]

    return output

# Test input
test_in = [[1, 2, 5], [7, 3, 6], [7, 6, 5]]
result = transform(test_in)
print("Test input:")
for row in test_in:
    print(row)
print("\nOutput:")
for row in result:
    print(row)

print("\nJSON:", json.dumps(result))

